    // syn_CD8_C1.PDL1 = (C1_PDL1_base / A_cell) * syn_CD8_C1
    _species_var[SP_syn_CD8_C1_PDL1] = (PARAM(P_C1_PDL1_base) / PARAM(P_A_cell)) * PARAM(P_syn_CD8_C1);
